SELECT DISTINCT m.chembl_id AS chembl_id, m.pref_name AS compound_name, cs.canonical_smiles FROM molecule_dictionary m JOIN compound_records cr ON m.molregno = cr.molregno JOIN docs d ON cr.doc_id = d.doc_id LEFT JOIN compound_structures cs ON m.molregno = cs.molregno WHERE d.chembl_id = 'CHEMBL5727212' ORDER BY m.chembl_id, m.pref_name, cs.canonical_smiles
